/*# sourceMappingURL=ohmylms-rtl.css.map*/

.ohmylms-import-preview {
	margin: var(--oml-space-3) 0;
}

.ohmylms-import-preview__headline {
	margin: 0 0 var(--oml-space-2);
	font-weight: var(--oml-weight-strong);
}

.ohmylms-import-list {
	max-height: 220px;
	margin: 6px 0 0 18px;
	padding: 0;
	overflow-y: auto;
	list-style: disc;
}

.ohmylms-movable-tabs {
	align-items: center;
	gap: 6px var(--oml-space-4);
	--ohmylms-hub-gutter: 0px;
}

.ohmylms-tab-group {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: var(--oml-space-3);
	border-radius: 8px 8px 0 0;
	padding: 0 var(--oml-space-3);
	border-bottom: 3px solid currentcolor;
}

.ohmylms-tab-group-label {
	font: inherit;
	color: inherit;
	background: transparent;
	border: 0;
	padding: var(--oml-space-2) var(--oml-space-1);
	cursor: pointer;
	cursor: grab;
	font-weight: var(--oml-weight-strong);
}

.ohmylms-tab-organize {
	font: inherit;
	background: transparent;
	border: 0;
	padding: var(--oml-space-2) var(--oml-space-1);
	cursor: pointer;
	margin-left: auto;
	font-size: var(--oml-font-size-xs);
	color: var(--ohmylms-admin-muted-color, var(--oml-muted));
}

.ohmylms-tab-ungroup {
	padding: var(--oml-space-2);
	border: 1px dashed var(--oml-border);
	font-size: var(--oml-font-size-xs);
}

.ohmylms-tab-save-status {
	margin: -var(--oml-space-4) var(--ohmylms-hub-gutter, 0px) var(--oml-space-4);
	font-size: var(--oml-font-size-xs);
}

.ohmylms-tab-modal {
	width: min(760px, 95vw);
}

.ohmylms-tab-assignments {
	margin: 20px 0;
}

.ohmylms-tab-modal-footer {
	display: flex;
	justify-content: space-between;
	gap: var(--oml-space-3);
}

.ohmylms-tab-panel-body {
	min-width: 0;
}

/* Page header: title and description on the left, actions on the right. */

/* Content Hub: title, the section tabs, then the active tab's body. It supplies its own
 * gutter, and drops it when opened through a legacy extension URL, which already has one. */

.ohmylms-catalog-items {
	margin: 0;
	margin-block: 6px 0;
	margin-inline-start: 3.25rem;
	padding: 0;
	list-style: none;
}

.ohmylms-catalog-item {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 2px var(--oml-space-2);
	padding: var(--oml-space-1) 0;
	font-size: var(--oml-font-size-sm);
}

.ohmylms-catalog-item-title {
	min-width: 0;
	overflow-wrap: anywhere;
	font-weight: var(--oml-weight-medium);
}

.ohmylms-catalog-item-controls {
	display: inline-flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--oml-space-1) var(--oml-space-3);
	margin-inline-start: auto;
}

.ohmylms-catalog-type {
	padding: 1px var(--oml-space-2);
	border-radius: var(--oml-radius-control);
	font-size: 11px;
	font-weight: var(--oml-weight-strong);
	letter-spacing: 0.02em;
	text-transform: uppercase;
	background: var(--oml-info-soft);
	color: var(--oml-info-text);
}

.ohmylms-catalog-flag {
	display: inline-block;
	padding: 1px var(--oml-space-2);
	border-radius: var(--oml-radius-control);
	font-size: var(--oml-font-size-xs);
	background: var(--ohmylms-admin-subtle, var(--oml-background));
	color: var(--ohmylms-admin-muted-color, var(--oml-muted));
}

.ohmylms-hub-chips {
	display: flex;
	flex-wrap: wrap;
	gap: var(--oml-space-1) 6px;
	margin: 0 0 var(--oml-space-1);
	padding: 0;
	list-style: none;
}

.ohmylms-hub-links {
	display: flex;
	flex-wrap: wrap;
	gap: var(--oml-space-1) 6px;
	margin: 0 0 var(--oml-space-1);
	padding: 0;
	list-style: none;
}

.ohmylms-hub-pager {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: var(--oml-space-3);
	margin-block-start: var(--oml-space-4);
}

/* Lessons, quizzes and assignments attached to a chapter of a syllabus course: a type tag, the title as a
 * link, flags, and the controls that say whether each one counts. */

.ohmylms-cur-syllabus-badge {
	background: var(--ohmylms-primary-soft-color, var(--oml-primary-soft));
	border-color: var(--ohmylms-primary-color, var(--oml-primary));
	font-weight: var(--oml-weight-strong);
}

.ohmylms-cur-name-link {
	color: var(--ohmylms-primary-color, var(--oml-primary));
	text-decoration: none;
}

.ohmylms-cur-syllabus-summary {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: var(--oml-space-3) 20px;
	margin: 20px 0 var(--oml-space-2);
	padding: 14px var(--oml-space-4);
	border: 1px solid var(--ohmylms-admin-border, var(--oml-border));
	border-radius: var(--ohmylms-admin-radius, 7px);
	background: var(--ohmylms-admin-surface, var(--oml-surface));
}

.ohmylms-syl-existing {
	margin: var(--oml-space-2) 0;
}

.ohmylms-syl-import {
	width: min(920px, calc(100vw - 32px));
}

.ohmylms-syl-options {
	display: grid;
	gap: var(--oml-space-2);
	margin: var(--oml-space-2) 0 var(--oml-space-3);
}

.ohmylms-syl-report {
	margin: var(--oml-space-2) 0;
}

.ohmylms-ws {
	--ws-muted: color-mix(
		in srgb,
		var(--ohmylms-admin-text-color, var(--oml-heading)) 68%,
		var(--oml-surface)
	);
	--ws-border: var(--ohmylms-admin-border, var(--oml-border));
	--ws-primary: var(--ohmylms-primary-color, var(--oml-primary));
	--ws-soft: var(--ohmylms-primary-soft-color, var(--oml-primary-soft));
	--ws-subtle: var(--ohmylms-admin-subtle, var(--oml-background));
	display: flex;
	flex-direction: column;
	height: calc(100vh - 32px);
	min-height: 520px;
	background: var(--ohmylms-admin-surface, var(--oml-surface));
	color: var(--ohmylms-admin-text-color, var(--oml-heading));
}

/* Narrow editors use a branching vertical layout instead of a wide canvas. */
@container ohmylms-mindmap (max-width: 1000px) {

	.ohmylms-mindmap-stage {
		display: block;
		width: 100%;
		min-width: 0;
	}

	.ohmylms-mindmap-node {
		width: 100%;
		min-width: 0;
	}

	.ohmylms-mindmap-root {
		width: 100%;
		min-width: 0;
		margin-bottom: var(--oml-space-4);
	}

	.ohmylms-mindmap-branches {
		padding-left: var(--oml-space-4);
		min-width: 0;
	}

	.ohmylms-mindmap-root::after {
		display: none;
	}

	.ohmylms-mindmap-branches > li {
		flex-direction: column;
		align-items: stretch;
		gap: 0;
		min-width: 0;
	}

	.ohmylms-mindmap-branches > li::before {
		top: 24px;
		left: -16px;
		width: 16px;
	}

	.ohmylms-mindmap-node.has-children::after {
		display: none;
	}
}

/* Small screens: narrower gutter. */
@media (max-width: 782px) {

	.ohmylms-dashboard-layout.extensions .ohmylms-content {
		padding: var(--oml-space-4) var(--oml-space-3) var(--oml-space-6);
	}
}

/* Curriculum accordion editor and Course Bundles manager. Indentation comes from nesting,
 * so every inline panel, add row and child list lines up with its parent. Logical properties
 * keep right-to-left layouts correct. */

.ohmylms-form-settings-bar {
	margin: 20px 0 0;
	padding: var(--oml-space-4);
	border: 1px solid var(--oml-border, var(--oml-border));
	border-radius: var(--oml-radius-card, 8px);
	background: var(--ohmylms-admin-surface-subtle, var(--oml-background));
}

.ohmylms-category-tags {
	display: flex;
	align-items: center;
	gap: var(--oml-space-2);
	flex-wrap: wrap;
	border: 1px solid var(--oml-border);
	border-radius: var(--oml-radius-control);
	background: var(--oml-surface);
	padding: 10px var(--oml-space-3);
	min-height: 52px;
}

.ohmylms-category-token {
	display: inline-flex;
	align-items: center;
	gap: var(--oml-space-2);
	padding: 5px 10px 5px 13px;
	background: var(--oml-success-soft);
	color: var(--oml-success-text);
	border: 1px solid var(--oml-success-soft);
	border-radius: var(--oml-radius-card);
	font-weight: var(--oml-weight-strong);
	font-size: var(--oml-font-size-sm);
	line-height: 22px;
}

.ohmylms-category-add {
	border: 0;
	border-radius: var(--oml-radius-card, 7px);
	background: var(--oml-primary-soft);
	color: var(--oml-primary-hover, var(--oml-primary));
	padding: 6px var(--oml-space-3);
	cursor: pointer;
	font-weight: var(--oml-weight-strong);
}

.ohmylms-category-appearance {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 10px;
	padding: var(--oml-space-2) 0;
	border-bottom: 1px solid var(--ws-border);
}

.ohmylms-assessment-editor-tabs {
	display: flex;
	gap: var(--oml-space-2);
	background: var(--oml-surface);
	border-bottom: 1px solid var(--oml-border);
	padding: var(--oml-space-2) var(--oml-space-4);
}

.ohmylms-preview-note {
	color: var(--oml-muted);
	font-size: var(--oml-font-size-sm);
}

.ohmylms-preview-choice {
	display: flex;
	gap: var(--oml-space-3);
	padding: var(--oml-space-3) 0;
	align-items: center;
}

.ohmylms-preview-input {
	display: flex;
	gap: var(--oml-space-3);
	padding: var(--oml-space-3) 0;
	flex-direction: column;
	align-items: stretch;
}

.ohmylms-preview-blank {
	width: 120px;
	margin: 0 6px;
}

.ohmylms-form-actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--oml-space-3);
	margin: 0 auto 20px;
	max-width: 1100px;
}

.ohmylms-form-add-bottom {
	margin-top: 20px;
}

.ohmylms-form-workspace {
	background: var(--oml-surface);
	padding: var(--oml-space-5);
	border-radius: var(--oml-radius-card, 8px);
}

.ohmylms-form-workspace-actions {
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-end;
	gap: var(--oml-space-3);
	margin-bottom: 20px;
}

.ohmylms-form-description {
	margin: 20px 0;
}

.ohmylms-form-response-fields {
	border: 0;
	margin: 0;
	padding: 0;
	min-width: 0;
}

@media (max-width: 782px) {

	.ohmylms-cur-status {
		top: 46px;
	}

	.ohmylms-cur-actions {
		flex: 1 0 100%;
		margin-inline-start: 38px;
	}

	.ohmylms-cur-children {
		margin-inline-start: 10px;
	}

	.ohmylms-cur-node > .ohmylms-cur-add-wrap {
		margin-inline-start: 10px;
	}

	.ohmylms-cur-toolbar .components-base-control {
		min-width: 0;
		flex: 1 1 100%;
	}

	.ohmylms-cur-move .components-base-control {
		min-width: 0;
		flex: 1 1 100%;
	}

	.ohmylms-cur-add .components-base-control {
		min-width: 0;
		flex: 1 1 100%;
	}
}

/* Syllabus: any curriculum item can be one. The item panel only summarises it and opens the syllabus workspace
 * (styled further down), where its topics, chapters and skills are edited. */

.ohmylms-shared-answers {
	display: grid;
	gap: var(--oml-space-3);
}

.ohmylms-inline-blank-stem {
	font-size: var(--oml-font-size-lg);
	line-height: 2.2;
}

.ohmylms-blank-drop {
	display: inline-block;
	min-width: 100px;
	padding: 3px 10px;
	margin: 0 var(--oml-space-1);
	font: inherit;
	border: 1px dashed var(--oml-border);
	border-radius: var(--oml-radius-control);
	background: var(--oml-subtle);
	cursor: pointer;
}

.ohmylms-blank-answer-bank {
	display: flex;
	flex-wrap: wrap;
	gap: var(--oml-space-2);
	margin: var(--oml-space-3) 0;
}

/* Skill library picker inside a chapter, and the import dialog. */

.ohmylms-blank-answer-chip {
	border: 1px solid var(--oml-border, var(--oml-border));
	padding: 6px var(--oml-space-3);
	border-radius: var(--oml-radius-control);
	background: var(--oml-subtle);
}

.ohmylms-shared-answer-row {
	display: flex;
	align-items: center;
	gap: 10px;
	flex-wrap: wrap;
	margin: 0;
	padding: 10px 0;
	border: 0;
	min-width: 0;
}

/* Syllabus workspace: the full-page editor, laid out like the course builder. The outline (topics, chapters
 * and skills) is on the left and whatever is selected is on the right. A chapter is a skill group and a
 * chapter of the syllabus's course. Logical properties keep right-to-left layouts correct. */

.ohmylms-shared-answer-correct {
	flex: 0 0 auto;
	accent-color: var(--oml-primary);
}

.ohmylms-shared-answer-image {
	flex-basis: 100%;
	display: flex;
	align-items: center;
	gap: var(--oml-space-3);
}

.ohmylms-form-settings {
	margin-top: var(--oml-space-5);
	padding-top: var(--oml-space-4);
	border-top: 1px solid var(--oml-border);
}

.ohmylms-movable-tabs a {
	white-space: nowrap;
	cursor: grab;
}

.ohmylms-tab-group-editor fieldset {
	display: flex;
	align-items: end;
	flex-wrap: wrap;
	gap: var(--oml-space-3);
	border: 1px solid var(--oml-border, var(--oml-border));
	padding: var(--oml-space-3);
	margin-bottom: var(--oml-space-3);
}

.ohmylms-tab-group-editor label {
	display: flex;
	flex-direction: column;
	gap: 6px;
}

.ohmylms-tab-assignments > div {
	display: flex;
	align-items: center;
	gap: var(--oml-space-2);
	margin: 10px 0;
}

.ohmylms-tab-assignments label {
	display: flex;
	align-items: center;
	justify-content: space-between;
	flex: 1;
	gap: var(--oml-space-3);
}

.ohmylms-ext-header h2 {
	margin: 0;
	padding: 0;
	font-size: var(--oml-font-size-lg);
	line-height: 1.4;
	font-weight: var(--oml-weight-strong);
	color: var(--ohmylms-admin-heading-color, var(--oml-heading));
}

.ohmylms-hub-chips li {
	margin: 0;
	padding: 1px var(--oml-space-2);
	border-radius: var(--oml-radius-control);
	font-size: var(--oml-font-size-xs);
	background: var(--ohmylms-primary-soft-color, var(--oml-primary-soft));
	color: var(--ohmylms-primary-color, var(--oml-primary));
}

.ohmylms-hub-links li {
	margin: 0;
}

/* Right pane */

.ohmylms-ext-header h1 {
	margin: 0;
	padding: 0;
	font-size: var(--oml-font-size-xl);
	line-height: 1.4;
	font-weight: var(--oml-weight-strong);
	color: var(--ohmylms-admin-heading-color, var(--oml-heading));
}

.ohmylms-ext-header p {
	margin: var(--oml-space-1) 0 0;
	max-width: 760px;
	font-size: var(--oml-font-size-md);
	color: var(--ohmylms-admin-muted-color, var(--oml-muted));
}

.ohmylms-mindmap > summary {
	cursor: pointer;
	font-weight: var(--oml-weight-strong);
}

.ohmylms-mindmap-root::after {
	content: "";
	position: absolute;
	top: 50%;
	right: -25px;
	width: 24px;
	border-top: 1px solid var(--ohmylms-admin-border, var(--oml-border));
}

.ohmylms-mindmap-node-heading label {
	display: flex;
	align-items: center;
	gap: var(--oml-space-2);
	font-weight: var(--oml-weight-strong);
	cursor: pointer;
}

.ohmylms-mindmap-node-heading input {
	flex-shrink: 0;
	margin: 0;
}

.ohmylms-mindmap-node-heading button {
	flex-shrink: 0;
	width: 28px;
	height: 28px;
	border: 1px solid var(--ohmylms-admin-border, var(--oml-border));
	border-radius: var(--oml-radius-control, 4px);
	background: var(--ohmylms-admin-surface, var(--oml-surface));
	cursor: pointer;
}

.ohmylms-mindmap-node small {
	display: block;
	margin-top: var(--oml-space-2);
	color: var(--ohmylms-admin-muted-color, var(--oml-muted));
}

.ohmylms-mindmap-branches > li {
	position: relative;
	display: flex;
	align-items: center;
	gap: var(--oml-space-5);
	margin: var(--oml-space-3) 0;
}

.ohmylms-mindmap-node-details summary {
	cursor: pointer;
}

.ohmylms-mindmap-node-details ul {
	list-style: disc;
	padding-left: 18px;
	margin: var(--oml-space-2) 0 0;
}

.ohmylms-ext-card > h2 {
	margin: 0 0 var(--oml-space-3);
	font-size: var(--oml-font-size-lg);
	font-weight: var(--oml-weight-strong);
	color: var(--ohmylms-admin-heading-color, var(--oml-heading));
}

.ohmylms-ext-card > h3 {
	margin: 0 0 var(--oml-space-3);
	font-size: var(--oml-font-size-lg);
	font-weight: var(--oml-weight-strong);
	color: var(--ohmylms-admin-heading-color, var(--oml-heading));
}

.ohmylms-cur-syllabus-shortcuts li {
	display: flex;
	align-items: baseline;
	gap: 10px;
	margin: 0;
	padding: var(--oml-space-1) 0;
}

.ohmylms-cur-panel h3 {
	margin: 20px 0 var(--oml-space-2);
	font-size: var(--oml-font-size-md);
}

.ohmylms-cur-link-group > summary {
	cursor: pointer;
	font-weight: var(--oml-weight-strong);
}

.ohmylms-cur-mapping > summary {
	cursor: pointer;
	font-weight: var(--oml-weight-strong);
}

.ohmylms-cur-link-list li {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px 10px;
	padding: 6px 0;
	border-bottom: 1px solid var(--ohmylms-admin-border, var(--oml-border));
}

.ohmylms-bundle-members > li {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px var(--oml-space-3);
	padding: var(--oml-space-2) 0;
	border-bottom: 1px solid var(--ohmylms-admin-border, var(--oml-border));
}

.ohmylms-cur-syllabus-summary p {
	margin: 0 0 var(--oml-space-1);
}

.ohmylms-syl-existing summary {
	cursor: pointer;
}

.ohmylms-syl-map th {
	min-width: 160px;
	vertical-align: top;
	font-weight: var(--oml-weight-regular);
}

.ohmylms-syl-map td {
	max-width: 260px;
	overflow-wrap: anywhere;
}

.ohmylms-syl-report th {
	text-align: start;
}

.ohmylms-syl-report td {
	text-align: start;
}

.ohmylms-syl-problems ul {
	margin: 0 0 0 18px;
	list-style: disc;
}

.ohmylms-category-token button {
	border: 0;
	background: transparent;
	color: inherit;
	border-radius: 50%;
	font-size: 19px;
	line-height: 22px;
	width: 22px;
	height: 22px;
	cursor: pointer;
	padding: 0;
}

.ohmylms-category-tags input {
	flex: 1;
	min-width: 160px;
	width: auto !important;
	border: 0 !important;
	box-shadow: none !important;
	background: transparent !important;
	padding: 5px !important;
	margin: 0 !important;
	outline: 0;
}

.ohmylms-category-appearance > strong {
	min-width: 90px;
}

.ohmylms-category-appearance label {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	font-size: var(--oml-font-size-xs);
}

.ohmylms-form-description > label {
	display: block;
	margin-bottom: var(--oml-space-2);
	font-size: var(--oml-font-size-sm);
	font-weight: var(--oml-weight-medium);
}

.ohmylms-form-settings > fieldset {
	border: 0;
	margin: 0;
	padding: 0;
	min-width: 0;
}

.ohmylms-shared-answer-image img {
	max-width: 160px;
	max-height: 120px;
	object-fit: contain;
}

.ohmylms-form-settings > summary {
	cursor: pointer;
	font-weight: var(--oml-weight-strong);
	margin-bottom: var(--oml-space-4);
}

.ohmylms-mindmap-branches > li::before {
	content: "";
	position: absolute;
	top: 50%;
	left: -24px;
	width: 24px;
	border-top: 1px solid var(--ohmylms-admin-border, var(--oml-border));
}

.ohmylms-tab-group-label.is-active {
	text-decoration: underline;
	text-underline-offset: 4px;
}

.ohmylms-movable-tabs .is-drop-target {
	outline: 2px dashed var(--ohmylms-primary-color, var(--oml-primary));
	outline-offset: 2px;
}

.ohmylms-movable-tabs .is-dragging {
	opacity: 0.45;
}

.ohmylms-movable-tab-panel > .ohmylms-movable-tabs {
	margin-inline: 0;
}

.ohmylms-movable-tab-panel.is-vertical {
	display: grid;
	grid-template-columns: minmax(200px, 240px) minmax(0, 1fr);
	gap: var(--oml-space-5);
}

.ohmylms-catalog-item-controls .components-base-control {
	margin-bottom: 0;
}

.ohmylms-catalog-items.is-chapter {
	margin: 0 0 var(--oml-space-2);
}

.ohmylms-catalog-item-controls .components-text-control__input {
	width: 4.5rem;
	min-height: 28px;
}

.ohmylms-catalog-type.is-quiz {
	background: var(--oml-warning-soft);
	color: var(--oml-warning-text);
}

.ohmylms-catalog-type.is-assignment {
	background: var(--oml-success-soft);
	color: var(--oml-success-text);
}

.ohmylms-catalog-flag.is-ok {
	background: var(--oml-success-soft);
	color: var(--oml-success-text);
}

.ohmylms-catalog-flag.is-warning {
	background: var(--oml-warning-soft);
	color: var(--oml-warning-text);
}

/* Adding things one after another */

.ohmylms-mindmap-node.is-included {
	border-color: var(--ohmylms-primary-color, var(--oml-primary));
	background: var(--ohmylms-primary-soft-color, var(--oml-primary-soft));
}

.ohmylms-ext-toolbar .components-base-control {
	margin-bottom: 0;
}

.ohmylms-ext-toolbar .components-base-control__field {
	margin-bottom: 0;
}

.ohmylms-cur-status .components-notice {
	margin: 0 0 var(--oml-space-3);
	box-shadow: var(--oml-shadow-sm);
}

/* What a skill owns */

.ohmylms-cur-toolbar .components-base-control {
	min-width: 240px;
}

.ohmylms-cur-row.is-editing {
	background: var(--ohmylms-admin-subtle, var(--oml-background));
}

.ohmylms-cur-row.is-match {
	background: var(--ohmylms-primary-soft-color, var(--oml-primary-soft));
	box-shadow: var(--oml-shadow-sm);
}

.ohmylms-cur-toggle:focus-visible {
	outline: 2px solid var(--ohmylms-primary-color, var(--oml-primary));
	outline-offset: 2px;
}

.ohmylms-cur-details .components-textarea-control {
	grid-column: 1 / -1;
}

.ohmylms-cur-details .ohmylms-cur-save {
	grid-column: 1 / -1;
}

.ohmylms-cur-move .components-base-control {
	min-width: 260px;
}

.ohmylms-cur-node > .ohmylms-cur-add-wrap {
	margin-inline-start: 20px;
}

.ohmylms-cur-add .components-base-control {
	min-width: 220px;
}

.ohmylms-cur-delete.is-confirming {
	padding: var(--oml-space-3) var(--oml-space-4);
	border: 1px solid var(--oml-danger, var(--oml-danger));
	border-radius: var(--oml-radius-control, 4px);
	background: var(--ohmylms-admin-surface, var(--oml-surface));
}

.ohmylms-cur-delete .is-confirming {
	padding: var(--oml-space-3) var(--oml-space-4);
	border: 1px solid var(--oml-danger, var(--oml-danger));
	border-radius: var(--oml-radius-control, 4px);
	background: var(--ohmylms-admin-surface, var(--oml-surface));
}

.ohmylms-cur-name-link:hover {
	text-decoration: underline;
}

.ohmylms-cur-name-link:focus-visible {
	text-decoration: underline;
}

.ohmylms-syl-frame:focus {
	outline: none;
}

.ohmylms-category-tags:focus-within {
	border-color: var(--oml-primary-hover, var(--oml-primary));
	box-shadow: var(--oml-shadow-sm);
}

.ohmylms-assessment-editor-tabs [aria-selected="true"] {
	color: var(--oml-primary-hover, var(--oml-primary));
	box-shadow: var(--oml-shadow-sm);
}

@media (max-width: 782px) {

	.ohmylms-ws {
		height: auto;
		min-height: 0;
	}

	.ohmylms-ws-body {
		flex-direction: column;
	}

	.ohmylms-ws-side {
		flex-basis: auto;
		width: auto;
		border-inline-end: 0;
		border-bottom: 1px solid var(--ws-border);
	}

	.ohmylms-ws-side-body {
		max-height: 40vh;
	}

	.ohmylms-ws-main {
		padding: 0 var(--oml-space-4) var(--oml-space-7);
		overflow: visible;
	}

	.ohmylms-ws-title {
		font-size: var(--oml-font-size-2xl);
	}

	.ohmylms-ws-header {
		padding: 10px 14px;
	}

	.ohmylms-ws-side.is-collapsed {
		flex-basis: auto;
		width: auto;
		border-inline-end: 0;
		border-bottom: 1px solid var(--ws-border);
	}

	.ohmylms-ws-side.is-collapsed .ohmylms-ws-add-chapter {
		display: inline-flex;
	}

	.ohmylms-ws-side.is-collapsed .ohmylms-ws-side-count {
		display: inline-flex;
	}

	.ohmylms-ws-side.is-collapsed .ohmylms-ws-side-tools.is-header {
		display: inline-flex;
	}
}

/* Syllabus-level category tags; skill panes use a selection-only dropdown. */

.ohmylms-form-description [role="toolbar"] {
	border: 1px solid var(--oml-border, var(--oml-border));
	background: var(--oml-subtle);
	display: flex;
}

.ohmylms-form-description [role="textbox"] {
	min-height: 80px;
	border: 1px solid var(--oml-border, var(--oml-border));
	border-top: 0;
	padding: var(--oml-space-3);
	outline-color: var(--oml-primary-hover, var(--oml-primary));
}

.ohmylms-shared-answers > .components-button {
	justify-self: start;
}

.ohmylms-shared-answer-row > .components-base-control {
	flex: 1 1 180px;
	margin: 0;
}

.ohmylms-shared-answer-row .components-base-control__field {
	margin-bottom: 0;
}

.ohmylms-shared-answer-row > .components-button {
	flex: 0 0 auto;
	min-width: 30px;
}

.ohmylms-movable-tabs .ohmylms-tab-group a {
	color: inherit;
}

.ohmylms-tab-group-editor input[type="color"] {
	width: 64px;
	height: 32px;
}

.ohmylms-ext-header > div:first-child {
	flex: 1 1 360px;
	min-width: 0;
}

.ohmylms-mindmap-node.has-children::after {
	content: "";
	position: absolute;
	top: 50%;
	right: -25px;
	width: 24px;
	border-top: 1px solid var(--ohmylms-admin-border, var(--oml-border));
}

.ohmylms-cur-panel .ohmylms-cur-syllabus-summary h3 {
	margin: 0 0 2px;
}

.ohmylms-syl-map td.is-ignored {
	opacity: 0.45;
}

.ohmylms-action-confirmation button + button { margin-inline-start: var(--oml-space-3); }

.ohmylms-category-token button:hover {
	background: var(--oml-success-soft);
}

.ohmylms-category-tags button:disabled {
	opacity: 0.5;
	cursor: default;
}

.ohmylms-category-tags button:focus-visible {
	outline: 2px solid var(--oml-primary-hover, var(--oml-primary));
	outline-offset: 2px;
}

.ohmylms-form-workspace > .components-base-control input {
	font-size: var(--oml-font-size-xl);
	padding: var(--oml-space-3);
	background: var(--oml-subtle);
}

.ohmylms-form-description [role="textbox"] img {
	max-width: 100%;
	height: auto;
}

.ohmylms-cur-link-list li > span:first-child {
	flex: 1 1 200px;
	min-width: 0;
	overflow-wrap: anywhere;
}

.ohmylms-dashboard-layout.extensions .ohmylms-content {
	padding: 26px var(--ohmylms-admin-gutter, 40px) 40px;
	color: var(--ohmylms-admin-text-color, var(--oml-heading));
}

.ohmylms-movable-tab-panel.is-vertical > .ohmylms-movable-tabs {
	align-content: start;
	align-items: stretch;
	flex-direction: column;
	border-bottom: 0;
}

.ohmylms-movable-tab-panel.is-vertical .ohmylms-tab-group {
	align-items: stretch;
	flex-direction: column;
	gap: 0;
}

.ohmylms-movable-tab-panel.is-vertical .ohmylms-tab-organize {
	margin-left: 0;
	text-align: left;
}

.ohmylms-cur-syllabus-path .components-button.is-link {
	display: inline;
	height: auto;
	padding: 0;
	font-size: inherit;
	vertical-align: baseline;
}

.ohmylms-dashboard-layout.extensions .ohmylms-content > section > h1 {
	margin: 0;
	padding: 0;
	font-size: var(--oml-font-size-xl);
	line-height: 1.4;
	font-weight: var(--oml-weight-strong);
	color: var(--ohmylms-admin-heading-color, var(--oml-heading));
}

.ohmylms-dashboard-layout.extensions .ohmylms-content table.widefat {
	border: 0;
	border-radius: var(--ohmylms-admin-radius, 7px);
	box-shadow: none;
	border-collapse: separate;
	border-spacing: 0;
	overflow: hidden;
	background: var(--ohmylms-admin-surface, var(--oml-surface));
}
